const o=[{id:"S01",title:"Trauer et al. · 2015 · CBT-I for chronic insomnia",url:"https://doi.org/10.7326/M14-2841",type:"research",finding:"Across 20 trials with 1,162 adults, face-to-face multicomponent CBT-I reduced diary sleep-onset time by 19.03 minutes and nighttime wakefulness by 26.00 minutes. Total sleep increased 7.61 minutes, with a confidence interval spanning no difference.",limitation:"Abstract access. Narrow eligibility and inactive comparisons limit transfer. These are end-of-treatment averages, not ODA predictions; an inconclusive total-sleep difference does not negate continuity benefits."},{id:"S03",title:"Furukawa et al. · 2024 · Components of CBT-I",url:"https://jamanetwork.com/journals/jamapsychiatry/fullarticle/2814164?resultClick=1",type:"research",finding:"Component network analysis of 241 trials with 31,452 adults associated stimulus control and sleep restriction with remission benefit. Sleep hygiene alone had an incremental odds ratio of 1.01 (95% CI 0.77–1.32).",limitation:"Component modeling assumes additivity and is not isolated randomization of ingredients. Relaxation’s interval crossed one, so this does not show relaxation harms sleep. ODA is not CBT-I."},{id:"S04",title:"Edinger et al. · 2021 · AASM insomnia treatment guideline",url:"https://doi.org/10.5664/jcsm.8986",type:"guidance",finding:"Recommends multicomponent CBT-I strongly for chronic insomnia and conditionally discourages sleep hygiene as the sole treatment. Some individual components have conditional recommendations.",limitation:"Publisher recommendations accessed. This does not make supportive habit education useless or permit an app to prescribe sleep restriction."},{id:"S05",title:"American College of Physicians · 2016 · Initial insomnia treatment",url:"https://www.acponline.org/acp-newsroom/acp-recommends-cognitive-behavioral-therapy-as-initial-treatment-for-chronic-insomnia",type:"guidance",finding:"Recommends CBT-I as initial treatment for adult chronic insomnia. Delivery can include individual or group care, telephone or web modules, and structured self-help. Medication decisions require discussion with a clinician.",limitation:"Official guideline summary, not a trial. A chronic-insomnia duration definition is not a waiting requirement for assessment, and every digital product is not validated CBT-I."},{id:"S06",title:"NIH/NHLBI · 2022 · Insomnia treatment",url:"https://www.nhlbi.nih.gov/health/insomnia/treatment",type:"guidance",finding:"Describes CBT-I as a multicomponent treatment commonly over six to eight weeks, with in-person, phone, and online delivery. Stimulus control includes going to bed when sleepy and leaving if unable to sleep.",limitation:"Patient guidance, not a trial or permission for self-directed sleep restriction. Five ODA lessons do not reproduce the described treatment."},{id:"S07",title:"Watson et al. · 2015 · Adult sleep-duration consensus",url:"https://www.aasm.org/resources/pdf/adultsleepdurationconsensus.pdf",type:"guidance",finding:"For adults ages 18–60, recommends regularly sleeping at least seven hours. Individual need varies, and longer sleep can be appropriate during illness or recovery.",limitation:"Full consensus statement and methods accessed. This is a population recommendation, not an exact personal target. Time in bed is not the same as sleep; health associations do not establish individual causation."},{id:"S08",title:"CDC · 2024 · About sleep",url:"https://www.cdc.gov/sleep/about/index.html",type:"guidance",finding:"Sleep duration and quality both matter. Age-based recommendations vary. Regular sleep problems or disorder symptoms warrant care; an optional diary can record sleep, wake, naps, substances, and medications.",limitation:"Public guidance. A diary is not a prerequisite for contacting care, and meeting a duration recommendation does not rule out a sleep disorder."},{id:"S09",title:"Gardiner et al. · 2023 · Caffeine and subsequent sleep",url:"https://www.colegiomedico.cl/wp-content/uploads/2023/07/cafe-y-sueno.pdf",type:"research",finding:"Across 24 studies, caffeine impaired subsequent sleep on average. Objective total sleep was 45.3 minutes shorter (95% CI 29.0–61.5 shorter); amount and timing influenced outcomes.",limitation:"Full review accessed. This is not a prediction for one ordinary drink. Modeled cutoffs are not proven personal safety boundaries; sensitivity and habitual use vary."},{id:"S10",title:"FDA · How much caffeine is too much?",url:"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much",type:"guidance",finding:"For most adults, 400 mg daily is not generally associated with negative effects; sensitivity varies. Actual product and serving amounts differ. Gradual reduction can limit withdrawal symptoms.",limitation:"Consumer guidance, not a sleep-neutral allowance or intake target. Pregnancy, breastfeeding, medication, and condition questions require professional advice. Decaf can contain caffeine; update date was not verified."},{id:"S11",title:"NHS · 2024 · Insomnia",url:"https://www.nhs.uk/conditions/insomnia/",type:"guidance",finding:"Seek care if changes have not helped or sleep trouble makes daily life hard to cope with. Go to bed when sleepy and avoid driving while sleepy. Shift work, illness, and medicines can contribute.",limitation:"Three months describes persistence, not a waiting requirement. Public habit durations are suggestions, not individualized safe thresholds. This is guidance, not a diagnosis."},{id:"S12",title:"NHS · 2026 · Sleep apnea",url:"https://www.nhs.uk/conditions/sleep-apnoea/",type:"guidance",finding:"Breathing interruptions, gasping or choking, and excessive daytime sleepiness are reasons for medical evaluation. Symptoms can include frequent waking, loud snoring, headaches, and concentration problems.",limitation:"A symptom list does not diagnose apnea. Living alone or lacking a witness does not prevent assessment. Relaxation does not treat blocked breathing."},{id:"S13",title:"Drake et al. · 2013 · High-dose caffeine timing",url:"https://doi.org/10.5664/jcsm.3170",type:"research",finding:"In 12 healthy sleepers, one 400-mg dose disrupted sleep at zero, three, and six hours before bedtime versus placebo. The AASM summary reports over one hour less measured sleep at six hours.",limitation:"Primary abstract and official AASM summary accessed. Small, high-dose experiment; not a universal six-hour cutoff or prediction for tea. Exact effect confidence interval was unavailable."},{id:"S14",title:"Chang et al. · 2015 · Evening e-reader exposure",url:"https://doi.org/10.1073/pnas.1418490112",type:"research",finding:"Twelve healthy young adults read an iPad or print for four evening hours on five evenings each. E-reader exposure delayed sleep onset and melatonin timing; total sleep within the scheduled opportunity did not differ.",limitation:"Full published report accessed. A prolonged controlled exposure is not a brief phone glance, and this experiment did not test a 30-minute shutdown threshold."},{id:"S15",title:"He et al. · 2020 · Bedtime phone-use pilot",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0228756",type:"research",finding:"A randomized pilot with 38 willing university participants tested avoiding bedtime phone use for 30 minutes, using restrictions, reminders, and nightly checks. Self-reported outcomes favored the intervention.",limitation:"Small, unblinded pilot with exclusions and active adherence support. Results describe four weeks while Methods ambiguously mentions one week. The approximate 12-minute onset improvement is within-group, not the randomized between-group difference."},{id:"S17",title:"National Sleep Foundation · 2025 · Light and sleep",url:"https://www.thensf.org/good-light-bad-light-and-better-sleep/",type:"guidance",finding:"Suggests daytime outdoor light and dimmer evening light, including practical one-hour outdoor and screen-off periods.",limitation:"Public education without tested minimum doses. A window seat is not established as equivalent to outdoor exposure. Adapt to shifts, access, vision, mobility, and contact needs."},{id:"S19",title:"Stutz et al. · 2019 · Evening exercise and sleep",url:"https://doi.org/10.1007/s40279-018-1015-0",type:"research",finding:"Across 23 studies in healthy adults, evening exercise did not generally worsen sleep. Very vigorous exercise ending within an hour may differ.",limitation:"Abstract access. Moderator findings were sensitive to one study. This does not prove all late exercise harmless or transfer directly to people with insomnia; no universal evening exercise ban follows."},{id:"S20",title:"Schutte-Rodin et al. · 2008 · Stimulus control guidance",url:"https://aasm.org/resources/clinicalguidelines/040515.pdf",type:"guidance",finding:"Stimulus control responds to perceived sustained wakefulness, encourages a quiet alternative and return when sleepy, and discourages clock watching. Fatigue and sleepiness are distinct.",limitation:"Relevant full protocol accessed. Approximate minutes are not a biological threshold. Older diagnostic and medication guidance is not retained. Adapt nighttime movement with clinical guidance when access or safety is uncertain."},{id:"sleep-duration",title:"Watson et al. · 2015 · Adult sleep-duration consensus",url:"https://www.aasm.org/resources/pdf/adultsleepdurationconsensus.pdf",type:"guidance",finding:"For adults ages 18–60, recommends regularly sleeping at least seven hours. Individual need varies, and longer sleep can be appropriate during illness or recovery.",limitation:"Full consensus statement and methods accessed. This is a population recommendation, not an exact personal target. Time in bed is not the same as sleep; health associations do not establish individual causation."},{id:"cdc-sleep",title:"CDC · 2024 · About sleep",url:"https://www.cdc.gov/sleep/about/index.html",type:"guidance",finding:"Sleep duration and quality both matter. Age-based recommendations vary. Regular sleep problems or disorder symptoms warrant care; an optional diary can record sleep, wake, naps, substances, and medications.",limitation:"Public guidance. A diary is not a prerequisite for contacting care, and meeting a duration recommendation does not rule out a sleep disorder."},{id:"sleep-light",title:"National Sleep Foundation · 2025 · Light and sleep",url:"https://www.thensf.org/good-light-bad-light-and-better-sleep/",type:"guidance",finding:"Suggests daytime outdoor light and dimmer evening light, including practical one-hour outdoor and screen-off periods.",limitation:"Public education without tested minimum doses. A window seat is not established as equivalent to outdoor exposure. Adapt to shifts, access, vision, mobility, and contact needs."},{id:"sleep-habits",title:"Schutte-Rodin et al. · 2008 · Stimulus control guidance",url:"https://aasm.org/resources/clinicalguidelines/040515.pdf",type:"guidance",finding:"Stimulus control responds to perceived sustained wakefulness, encourages a quiet alternative and return when sleepy, and discourages clock watching. Fatigue and sleepiness are distinct.",limitation:"Relevant full protocol accessed. Approximate minutes are not a biological threshold. Older diagnostic and medication guidance is not retained. Adapt nighttime movement with clinical guidance when access or safety is uncertain."},{id:"caffeine-timing",title:"Drake et al. · 2013 · High-dose caffeine timing",url:"https://doi.org/10.5664/jcsm.3170",type:"research",finding:"In 12 healthy sleepers, one 400-mg dose disrupted sleep at zero, three, and six hours before bedtime versus placebo. The AASM summary reports over one hour less measured sleep at six hours.",limitation:"Primary abstract and official AASM summary accessed. Small, high-dose experiment; not a universal six-hour cutoff or prediction for tea. Exact effect confidence interval was unavailable."},{id:"caffeine-amounts",title:"FDA · How much caffeine is too much?",url:"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much",type:"guidance",finding:"For most adults, 400 mg daily is not generally associated with negative effects; sensitivity varies. Actual product and serving amounts differ. Gradual reduction can limit withdrawal symptoms.",limitation:"Consumer guidance, not a sleep-neutral allowance or intake target. Pregnancy, breastfeeding, medication, and condition questions require professional advice. Decaf can contain caffeine; update date was not verified."},{id:"nhs-insomnia",title:"NHS · 2024 · Insomnia",url:"https://www.nhs.uk/conditions/insomnia/",type:"guidance",finding:"Seek care if changes have not helped or sleep trouble makes daily life hard to cope with. Go to bed when sleepy and avoid driving while sleepy. Shift work, illness, and medicines can contribute.",limitation:"Three months describes persistence, not a waiting requirement. Public habit durations are suggestions, not individualized safe thresholds. This is guidance, not a diagnosis."},{id:"insomnia-self-help",title:"Schutte-Rodin et al. · 2008 · Stimulus control guidance",url:"https://aasm.org/resources/clinicalguidelines/040515.pdf",type:"guidance",finding:"Stimulus control responds to perceived sustained wakefulness, encourages a quiet alternative and return when sleepy, and discourages clock watching. Fatigue and sleepiness are distinct.",limitation:"Relevant full protocol accessed. Approximate minutes are not a biological threshold. Older diagnostic and medication guidance is not retained. Adapt nighttime movement with clinical guidance when access or safety is uncertain."},{id:"insomnia-guideline",title:"American College of Physicians · 2016 · Initial insomnia treatment",url:"https://www.acponline.org/acp-newsroom/acp-recommends-cognitive-behavioral-therapy-as-initial-treatment-for-chronic-insomnia",type:"guidance",finding:"Recommends CBT-I as initial treatment for adult chronic insomnia. Delivery can include individual or group care, telephone or web modules, and structured self-help. Medication decisions require discussion with a clinician.",limitation:"Official guideline summary, not a trial. A chronic-insomnia duration definition is not a waiting requirement for assessment, and every digital product is not validated CBT-I."},{id:"cbti-insomnia",title:"Trauer et al. · 2015 · CBT-I for chronic insomnia",url:"https://doi.org/10.7326/M14-2841",type:"research",finding:"Across 20 trials with 1,162 adults, face-to-face multicomponent CBT-I reduced diary sleep-onset time by 19.03 minutes and nighttime wakefulness by 26.00 minutes. Total sleep increased 7.61 minutes, with a confidence interval spanning no difference.",limitation:"Abstract access. Narrow eligibility and inactive comparisons limit transfer. These are end-of-treatment averages, not ODA predictions; an inconclusive total-sleep difference does not negate continuity benefits."},{id:"sleep-apnea",title:"NHS · 2026 · Sleep apnea",url:"https://www.nhs.uk/conditions/sleep-apnoea/",type:"guidance",finding:"Breathing interruptions, gasping or choking, and excessive daytime sleepiness are reasons for medical evaluation. Symptoms can include frequent waking, loud snoring, headaches, and concentration problems.",limitation:"A symptom list does not diagnose apnea. Living alone or lacking a witness does not prevent assessment. Relaxation does not treat blocked breathing."},{id:"sleep-cbti-overview",title:"NIH/NHLBI · 2022 · Insomnia treatment",url:"https://www.nhlbi.nih.gov/health/insomnia/treatment",type:"guidance",finding:"Describes CBT-I as a multicomponent treatment commonly over six to eight weeks, with in-person, phone, and online delivery. Stimulus control includes going to bed when sleepy and leaving if unable to sleep.",limitation:"Patient guidance, not a trial or permission for self-directed sleep restriction. Five ODA lessons do not reproduce the described treatment."}],i=[{schemaVersion:2,revision:2,id:"sleep-1",courseId:"sleep",locale:"en",title:"Still scrolling when tomorrow needs you?",goal:"End one optional activity to protect a realistic opportunity for rest.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Tomorrow starts while you are still saying “one more.” Choose what ends before your rest opportunity disappears.",reason:{id:"sleep-1-reason",label:"What needs your energy, and what can end earlier?",kind:"text",maxLength:160,optional:!0,suggestions:["Breakfast needs patience; videos can end","Tomorrow’s shift; optional email can wait","Care first; no safe activity to end"]},why:{id:"sleep-1-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["For adults ages 18 to 60, seven hours is a lower sleep recommendation, not an exact target. Seven hours in bed also does not mean seven hours asleep. Plan room for your own need rather than making bedtime another deadline.","Choose one optional activity to end before your intended rest period. Begin winding down, then go to bed when sleepy. Your experiment is the transition you control. Record that separately from sleep or morning energy. Adapt around shifts, care duties, and required contact. If adequate rest keeps being impossible, seek help with the conditions."],example:{title:"Daniel’s stopping point",text:"Daniel wants patience for breakfast with his daughter. At 9:30 p.m., he stops a replay and closes his laptop, leaving room before his early shift. He goes to bed when sleepy. A care call interrupts the evening. In the morning, he records the laptop closure and the interruption. He still feels tired."}},move:{invitation:"Keep your stopping cue. New plan? Name the activity and opening in this video example.",instructions:["Name your rest opportunity and an existing event that starts the transition.","End the named optional activity at that cue; go to bed when sleepy."],prompts:[],suggestions:{action:["Close optional videos after evening cleanup","Put optional work aside after dinner","End group chat after the goodnight message"],minimum:["Close the optional video session","Put one optional work item aside","Send goodnight and end group chat"],cue:["After tonight’s evening cleanup","After my last necessary task","After my planned goodnight message"],place:["On my living-room sofa","Beside my laptop","My accessible rest space"],minutes:[2,1,5],fallback:["Finish essential care, then close optional videos","Keep needed calls available","Ask for help protecting rest"],observation:["What I ended at the cue","Whether care changed the plan","Morning energy, recorded separately"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Close optional videos after evening cleanup",minimum:"Close the optional video session",minutes:2,cueHint:"After tonight’s evening cleanup",placeHint:"On my living-room sofa",obstacleHint:"An essential task or care need interrupts the cue",fallbackHint:"Finish essential care, then close optional videos",observationHint:"What I ended at the cue"},stopRule:"Avoid driving while sleepy. Seek care if sleep trouble affects coping.",accessibleAlternative:"Adapt the cue to shifts, disability, or care; keep necessary contact."},result:{question:"Did you end the activity you chose?",observationPrompt:"What ended, and what changed your available rest time?"},judgment:{primary:{id:"sleep-1-decision",scenario:"Daniel rises at 6 a.m. and usually needs more than seven hours. Optional videos keep him up past midnight.",question:"Which plan protects a useful opportunity?",options:[{id:"sleep-1-short-window",text:"End videos just before eleven, keeping a seven-hour opportunity and checking how he feels tomorrow.",feedback:"That protects some time, but seven hours is a population minimum rather than Daniel’s personal target. His known need asks for an earlier transition, without forcing sleep."},{id:"sleep-1-earlier-transition",text:"End optional videos earlier, start winding down, and record the transition separately from sleep quality.",feedback:"This changes what Daniel controls and leaves room for his known need. Going to bed when sleepy avoids turning a clock time into a demand to fall asleep."},{id:"sleep-1-weekend-recovery",text:"Keep tonight’s videos and arrange extra weekend rest, then revisit the schedule after the busy week.",feedback:"Extra rest may be useful, but this leaves tonight’s avoidable loss of opportunity unchanged. Daniel can protect tonight’s transition while adjusting his wider schedule and obligations."}],bestOptionId:"sleep-1-earlier-transition"}},carry:{takeaway:"Protect the opportunity. Report the transition and the night as different things.",followUp:{questionId:"sleep-1-return",question:"Did your stopping cue leave workable room for rest?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"A floor is not your personal target",paragraphs:["The AASM and Sleep Research Society consensus recommends at least seven hours regularly for adults ages 18 to 60 [S07]. It was developed by experts reviewing research, not by assigning every person a seven-hour night. Much of the health evidence is observational. Associations between short sleep and illness do not show that one short night caused a health problem.","The CDC gives different ranges for older adults: seven to nine hours at ages 61 to 64 and seven to eight at 65 or older [S08]. These remain population guidance. Quality, daytime functioning, illness, and recovery matter alongside duration. Your rest opportunity should allow for your own need and settling time. A recorded laptop closure is evidence of that action. It cannot establish how much you slept or diagnose why you remain tired."]},{heading:"Make room without forcing sleep",paragraphs:["NHS guidance advises going to bed when sleepy and seeking care when sleep difficulties make daily coping hard [S11]. A planning time can begin the transition away from an optional activity. It is not an instruction to lie awake because a calculated bedtime has arrived. A regular schedule can be useful, while shift work, care, disability, and housing may require an individualized arrangement.","This course follows one experiment: protect a workable rest opportunity, record the controllable move, and adjust a condition that actually blocked it. Later lessons offer changes when your record points to screens, caffeine, or wakeful struggle. They do not require collecting a new nightly ritual. If your obligations keep crowding out adequate rest, practical help or clinical advice may matter more than another reminder. Notes are optional and never a requirement before asking for support."]}],sourceIds:["S07","S08","S11"]}},{schemaVersion:2,revision:2,id:"sleep-2",courseId:"sleep",locale:"en",title:"Your phone needs a handover",goal:"Replace one optional screen interval while preserving its real function and necessary contact.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"You put the phone down, then pick it up again. What job did your wind-down leave unfinished?",reason:{id:"sleep-2-reason",label:"What does the screen provide that you still need?",kind:"text",maxLength:160,optional:!0,suggestions:["Connection with friends","An accessible audiobook","Overnight care calls","No need; scrolling reopened"]},why:{id:"sleep-2-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["One small laboratory study tested four hours of evening e-reader use, not a quick phone check. It changed sleep timing, but cannot tell you what one glance costs. A separate bedtime-phone pilot used reminders and nightly checks. A silent phone alone was not the tested program.","Use your rest-opportunity record. If optional screen use delayed your transition, choose a replacement that does the same job: earlier connection, accessible audio, or print reading. Try five offline minutes as a smaller personal experiment, without claiming the studied effect. Keep needed calls reachable. Otherwise, repeat your existing move."],example:{title:"Daniel keeps the connection",text:"Daniel’s record shows late group messages kept reopening his evening. At his wind-down cue, he sends a brief goodnight and uses five minutes of offline audio. Care calls remain audible. One message still tempts him back. He records the offline interval, rather than calling the whole evening screen-free or claiming better sleep."}},move:{invitation:"Keep a named replacement that works. New plan? Edit this offline-audio example if it serves your wind-down need.",instructions:["Change the screen interval only if it blocked your existing move.","Name the replacement, actual stopping cue, and reachable essential-contact channel before saving."],prompts:[],suggestions:{action:["Listen to downloaded audio after ending chat","Read print after sending a goodnight message","Close optional videos after evening cleanup"],minimum:["Listen to downloaded audio for five minutes","Read print for five minutes","Close the optional video session"],cue:["After tonight’s planned goodnight message","After my planned connection time","After evening cleanup, before another optional video"],place:["In my evening chair, care ringer audible","Near my reachable phone","My usual wind-down space"],minutes:[5,2,10],fallback:["End chat; keep care calls and audio","Use accessible offline audio","Read an available print book instead"],observation:["Audio used, minutes, and required access","Whether necessary contact stayed available","What reopened optional screen use"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Listen to downloaded audio after ending chat",minimum:"Listen to downloaded audio for five minutes",minutes:5,cueHint:"After tonight’s planned goodnight message",placeHint:"In my evening chair, care ringer audible",obstacleHint:"Optional chat reopens while my phone provides care access",fallbackHint:"End chat; keep care calls and audio",observationHint:"Audio used, minutes, and required access"},stopRule:"Keep essential contact and safe lighting; stop changes that obstruct care.",accessibleAlternative:"Use accessible audio or another replacement; required screen tools can stay."},result:{question:"Did you use the replacement you chose?",observationPrompt:"What replaced the screen, and what access did you preserve?"},judgment:{primary:{id:"sleep-2-decision",scenario:"Daniel needs overnight care calls. Group chat delayed his stopping cue yesterday. Print and downloaded audio are ready; his care ringer remains audible nearby.",question:"Which change fits both needs?",options:[{id:"sleep-2-dim-only",text:"Keep chatting in bed with the brightness reduced, preserving contact and his familiar evening connection.",feedback:"Lower brightness changes one feature, but the ongoing chat still displaced Daniel’s transition. He needs a stopping cue and a replacement while keeping necessary calls available."},{id:"sleep-2-remove-phone",text:"Read print beside the reachable care phone, leaving group chat open so he can finish replies between pages.",feedback:"This preserves care access and changes the reading format. But leaving chat open keeps the activity that delayed stopping. End optional replies before the replacement while keeping the care ringer available."},{id:"sleep-2-planned-handover",text:"End the chat at his cue, keep care calls audible, and use his offline replacement.",feedback:"This preserves necessary contact while changing the optional activity that delayed rest. Five offline minutes can test feasibility; it does not inherit the effects of a larger researched program."}],bestOptionId:"sleep-2-planned-handover"}},carry:{takeaway:"A workable screen boundary keeps the need and changes the delivery.",followUp:{questionId:"sleep-2-return",question:"Did your replacement serve the need without reopening optional screen use?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"What the device studies actually tested",paragraphs:["Chang and colleagues studied 12 healthy young adults in a controlled inpatient crossover experiment [S14]. Participants read an iPad or print from 6 to 10 p.m., with a short break, on five evenings per condition. E-reader exposure delayed sleep onset and melatonin timing. Total sleep did not differ within the scheduled eight-hour opportunity. That is a prolonged exposure, not evidence that every phone glance causes a particular sleep loss.","He and colleagues randomized 38 willing university participants with poor self-reported sleep [S15]. Their phone restriction included reminders, device restrictions or shutdown, and nightly checks. Results describe four weeks, while Methods ambiguously mentions one week. The trial was small and unblinded. Its roughly 12-minute onset improvement was a within-group change, not the randomized between-group difference. ODA’s voluntary handover, essential-contact exception, and five-minute minimum have not been tested as equivalents."]},{heading:"Light advice needs a real-life fit",paragraphs:["The National Sleep Foundation suggests outdoor daytime light and dimmer evening light [S17]. Its one-hour outdoor and screen-off durations are public recommendations, not verified minimum effective doses. Sitting beside a window may be accessible, but the guidance does not establish equivalence to outdoor exposure. Night shifts, weather, vision, mobility, and care needs also affect which arrangement is practical.","Choose one change that fits the existing rest experiment. If screen use is not delaying your transition, you can keep the move you already chose instead of adding a new cutoff. If light is the relevant issue, select safe lighting or an accessible daytime opportunity. Do not dim a path so far that moving becomes unsafe. Record what changed, whether the replacement met its purpose, and any access problem. A single better or worse morning cannot isolate what caused it."]}],sourceIds:["S14","S15","S17"]}},{schemaVersion:2,revision:2,id:"sleep-3",courseId:"sleep",locale:"en",title:"That late drink may follow you home",goal:"Replace or move one actual caffeine serving when your rest record makes it worth testing.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Falling asleep after coffee does not settle what the late serving costs.",reason:{id:"sleep-3-reason",label:"What makes this late drink worth its possible cost?",kind:"text",maxLength:160,optional:!0,suggestions:["It helps me finish essential work","I fall asleep; quality remains unknown","I haven’t compared mornings without it","No late serving to test"]},why:{id:"sleep-3-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Caffeine’s effect depends on amount, timing, and personal sensitivity. In a small experiment, one 400-milligram dose disrupted sleep even six hours before bed. That was a high dose, not an ordinary-cup prediction or proof that six hours is a safe boundary.","If your rest record points to a late serving, change that one serving: move it earlier, replace it, or reduce gradually. Note the actual product and time. Keep other major habits reasonably steady. The record can inform your next choice, but does not prove causation. If caffeine is irrelevant, continue your existing rest move."],example:{title:"Daniel tests one serving",text:"Daniel notices a large late coffee beside his laptop on two recorded evenings. Today he swaps that serving for his usual caffeine-free drink while finishing essential work. He leaves his morning coffee unchanged. He misses the lift and remains tired tomorrow. He records the substitution and timing before deciding whether to repeat it."}},move:{invitation:"Keep your serving. New plan? Edit this coffee-to-water example for your actual drink.",instructions:["Name the actual product, serving, cue, and replacement before saving this example.","Change only that serving; choose gradual reduction if an abrupt change is unsuitable."],prompts:[],suggestions:{action:["Replace my late coffee with water","Move one caffeine serving earlier","Reduce one habitual serving gradually"],minimum:["Drink water instead of late coffee","Drink one serving earlier","Use my chosen smaller serving"],cue:["When I reach for my evening coffee","Before my usual late break","At my existing drink cue"],place:["At my kitchen counter","At my usual drink station","Beside my work desk"],minutes:[2,1,5],fallback:["Use available water instead of late coffee","Take a suitable rest break","Seek advice on gradual reduction"],observation:["Product, serving, and actual time","Whether the planned serving changed","Morning functioning, recorded separately"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Replace my late coffee with water",minimum:"Drink water instead of late coffee",minutes:2,cueHint:"When I reach for my evening coffee",placeHint:"At my kitchen counter",obstacleHint:"My preferred caffeine-free drink is unavailable",fallbackHint:"Use available water instead of late coffee",observationHint:"Product, serving, and actual time"},stopRule:"Avoid sleepy driving. Keep medicines unchanged; ask a clinician about pregnancy, breastfeeding, or health concerns.",accessibleAlternative:"Use a gradual change or repeat your existing move if caffeine is irrelevant."},result:{question:"Did you change the serving you chose?",observationPrompt:"What drink, amount, and timing did you actually use?"},judgment:{primary:{id:"sleep-3-decision",scenario:"Daniel’s late coffee seems worth testing. He also wants to change meals, screens, and exercise this week.",question:"Which first test is easier to interpret?",options:[{id:"sleep-3-one-serving",text:"Replace the identified late coffee, note its timing, and leave other major habits reasonably steady.",feedback:"One identified change makes the record easier to interpret, though it cannot prove causation. Daniel can review feasibility and morning functioning before adding a different change to the same experiment."},{id:"sleep-3-under-limit",text:"Keep the coffee because his total is below the general daily limit, and record sleep duration.",feedback:"A general daily limit does not guarantee unaffected sleep. Amount, timing, and sensitivity still matter. Recording sleep without changing the identified serving does not test Daniel’s chosen question."},{id:"sleep-3-whole-overhaul",text:"Remove caffeine and shift meals, exercise, and screens together, then keep whatever seems to help.",feedback:"A broader overhaul changes several things at once and may be harder to sustain. Daniel would not know which change was relevant; an abrupt reduction can also need adjustment."}],bestOptionId:"sleep-3-one-serving"}},carry:{takeaway:"Change one relevant serving. A daily limit is not a promise about sleep.",followUp:{questionId:"sleep-3-return",question:"Did the serving change, and is this one change workable to repeat?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"Timing does not become a safety cutoff",paragraphs:["The often-cited Drake experiment involved 12 healthy sleepers and one 400-milligram dose on a caffeine day [S13]. It tested zero, three, or six hours before bedtime against placebo, not three high doses each day. The official AASM summary reports more than one hour less measured sleep at six hours. Exact effect confidence intervals were unavailable in the opened primary abstract.","This was a high single dose in a small group of healthy sleepers. It cannot predict the cost of your ordinary coffee or establish a universally safe six-hour cutoff. The useful question is which actual serving is worth changing and whether the change fits the job it does for you. Record the product, amount, and timing alongside your morning observation. One substitution is a practical experiment, not a treatment or proof of causation. Keep the other major habits reasonably steady when feasible."]},{heading:"An actual serving is more useful than a target",paragraphs:["The FDA’s general 400-milligram figure is not a goal and does not guarantee undisturbed sleep [S10]. Product amounts and serving sizes vary. Tea, soda, energy drinks, and some decaf drinks can contribute caffeine. Record your actual product and its label or usual serving rather than treating every household cup as interchangeable. Personal sensitivity and health circumstances can require professional advice.","This course’s substitution is a practical experiment, not a replicated trial dose. If you consume caffeine habitually, a gradual change may be more manageable than abruptly removing every serving. The FDA advises gradual reduction to limit withdrawal symptoms [S10]. Keep the purpose connected to your existing rest opportunity. Report the drink action even if the next night is unchanged. If sleep trouble makes daily coping hard, seek care without waiting for a perfect diary; avoid driving while sleepy [S11]."]}],sourceIds:["S10","S13","S11"]}},{schemaVersion:2,revision:2,id:"sleep-4",courseId:"sleep",locale:"en",title:"Stop making bedtime a contest",goal:"Use a safe quiet alternative if sustained wakefulness becomes a struggle, without watching the clock.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Another clock check, another calculation. Prepare a safe response to wakefulness without trying to win sleep.",reason:{id:"sleep-4-reason",label:"What do you do when being awake becomes a struggle?",kind:"text",maxLength:160,optional:!0,suggestions:["I check the clock repeatedly","I plan tomorrow from bed","I try to force sleep","No recent occasion"]},why:{id:"sleep-4-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Feeling drained is not the same as feeling sleepy. Sleepiness means you might drift off. Clinical guidance says: go to bed when sleepy, and choose a quiet alternative when sustained wakefulness becomes a struggle. Avoid clock watching. Twenty minutes is no biological deadline.","Use your existing rest experiment. If wakeful struggle appeared, arrange a safe, quiet activity and use it when needed; return when sleepy. Choose clinical guidance if getting up is unsafe or impractical. No occasion is a valid record. The controllable move is your response, not how quickly sleep arrives."],example:{title:"Daniel leaves the calculation",text:"Before wind-down, Daniel sets a book beside his living-room chair and checks the route and lamp. Later he notices sustained wakefulness and clock checking. He moves safely to the chair and reads, then returns when sleepy. He records preparation separately from the nighttime response. Sleep was still broken; he considers seeking help."}},move:{invitation:"Already prepared? Keep your response. Otherwise choose Adapt this, then Preparation, and edit this reading setup example. Check safety today.",instructions:["Preparation example: name a quiet activity and place; check the route before saving.","Keep preparation separate from nighttime use; use the response only if needed.","If movement is unsafe, pause and ask for individualized guidance before another trial."],prompts:[],suggestions:{action:["Set out print reading; check chair route","Arrange quiet audio; check safe seating","Check lamp and route to reading chair"],minimum:["Place book and check route to chair","Set audio ready and check seating","Check safe lighting and clear chair route"],cue:["After evening cleanup","After my last necessary evening task","Before settling into my rest space"],place:["Beside my living-room reading chair","At my accessible evening seat","Along the route to my reading chair"],minutes:[5,2,10],fallback:["Pause; ask for individualized guidance","Ask for help checking the safe route","Use a previously agreed accessible response"],observation:["Activity set ready and route safety checked","Whether I avoided clock checking","Response and sleep, recorded separately"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Set out print reading; check chair route",minimum:"Place book and check route to chair",minutes:5,cueHint:"After evening cleanup",placeHint:"Beside my living-room reading chair",obstacleHint:"The chair or nighttime route is unsafe or unavailable",fallbackHint:"Pause; ask for individualized guidance",observationHint:"Activity set ready and route safety checked",kind:"preparation"},stopRule:"Avoid sleepy driving. If movement is unsafe, pause this move and ask for individualized guidance.",accessibleAlternative:"Keep an actual clinician-agreed adaptation. Without one, request guidance; do not improvise an unsafe nighttime move."},result:{question:"Did you prepare the safe setup or use your chosen response?",observationPrompt:"What did you set ready, check, or use; was anything unsafe?"},judgment:{primary:{id:"sleep-4-decision",scenario:"Daniel has been wakeful and keeps checking the clock. His prepared quiet chair is safe to reach.",question:"Which response fits the plan?",options:[{id:"sleep-4-timed-checks",text:"Use twenty-minute reminders to decide when to move, then turn them off after the first attempt.",feedback:"A timer looks precise but turns perceived wakefulness into clock watching. The guidance discourages that. Daniel can notice sustained struggle and use the safe alternative without an elapsed-minute test."},{id:"sleep-4-safe-alternative",text:"Stop clock checking, use his quiet chair when struggle persists, and return when he feels sleepy.",feedback:"This follows the flexible response rather than a stopwatch. Daniel can report whether he used it and any access problem; falling asleep quickly is not the completion condition."},{id:"sleep-4-push-through",text:"Stay in bed for a planned relaxation session first, then decide by morning whether the plan worked.",feedback:"Relaxation may be comfortable. If wakeful struggle continues, use the safe alternative now; do not wait for a morning verdict to respond. Keep clock checking out of either choice."}],bestOptionId:"sleep-4-safe-alternative"}},carry:{takeaway:"Respond to wakeful struggle. Sleep arrival is not a task you can tick.",followUp:{questionId:"sleep-4-return",question:"Did you prepare the safe setup, or use it when needed, without clock watching?",observationPrompt:"Which part happened, and was anything unsafe or unavailable?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"Perceived wakefulness, not a stopwatch",paragraphs:["The AASM’s older clinical guideline describes stimulus control and explicitly advises avoiding clock watching [S20]. Its approximate twenty-minute cue refers to perceived wakefulness, not a measured biological threshold. The same guideline distinguishes fatigue, a sense of low energy, from sleepiness, the tendency to fall asleep. Those distinctions explain why an exhausted person need not force a clock-based bedtime.","The NIH overview includes going to bed when sleepy, leaving when unable to sleep, and returning to sleep-related use of the bed [S06]. These are parts of a broader clinical approach. They do not establish that every difficult night comes from worry or a weak bed association. ODA’s quiet alternative is education with practical adaptations, not a complete treatment. Your record asks whether the conditional response was needed and used, allowing no occasion when the situation did not arise."]},{heading:"A safe response comes before a rigid routine",paragraphs:["A quiet alternative requires safe access. Mobility limitations, fall risk, one-room housing, care duties, and shifts can make leaving bed unsuitable. An individualized clinician plan is preferable to copying an instruction that does not fit. Safe lighting matters more than making a path extremely dim. This course does not prescribe a reduced sleep window, ban a needed safety nap, or instruct you to change medication.","NHS guidance says not to drive when sleepy and recommends care when sleep difficulties impair coping [S11]. A regular schedule should be considered alongside adequate sleep opportunity and immediate safety. If the night is poor, do not treat keeping an early alarm as permission to drive dangerously. Bring the actual difficulty to care or practical support. Preparing the quiet space is preparation; using it during a needed response is a different attempt. Neither demonstrates improved sleep by itself."]}],sourceIds:["S06","S11","S20"]}},{schemaVersion:2,revision:2,id:"sleep-5",courseId:"sleep",locale:"en",title:"Bad nights are shrinking your life?",goal:"Review your rest experiment and carry forward one workable move or make a needed care request.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bad nights still affecting your day? Use any records to choose next week’s move or ask for care now.",reason:{id:"sleep-5-reason",label:"What is sleep trouble already costing your ordinary week?",kind:"text",maxLength:160,optional:!0,suggestions:["Too sleepy to travel safely","Daily tasks are hard","I miss time with people","No known impact yet"]},why:{id:"sleep-5-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sleep trouble need not last three months before you ask for help. Difficulty coping, unhelpful habit changes, gasping, breathing pauses, or persistent daytime sleepiness can justify assessment. Living alone and unfinished notes should not delay contact.","Review records from your existing rest experiment, including an untried plan. Keep one feasible rest move or request care now. No attempt yet? Choose a first opportunity. ODA is not structured insomnia treatment. Do not prescribe yourself less time in bed or change medicines."],example:{title:"Daniel asks before another overhaul",text:"Daniel’s records show he ended optional work on three nights, yet daytime sleepiness still makes his commute unsafe. He sends his clinic an assessment request describing the impact. He asks a colleague for a ride. The clinic has not answered by evening. He records the request and chooses the next contact opening as his fallback."}},move:{invitation:"Concerning signs or impaired coping? Choose Adapt this, then Support. Edit this care example for your next opening. Otherwise keep your rest move.",instructions:["Name your clinic, actual opening date, and private contact place before saving this care example.","If unanswered, choose another contact route now; do not wait for another rest trial.","Without concerning signs, keep your named rest move or choose Practice under Adapt."],prompts:[],suggestions:{action:["Call primary care for a sleep assessment","Send my clinic an assessment request","Ask a trusted person to arrange contact"],minimum:["Make one clinic contact attempt","Send one assessment request","Make one request for contact assistance"],cue:["At primary care’s next contact opening","After lunch, while my clinic is open","When an available appointment line opens"],place:["At my kitchen table, phone ready","In a private accessible contact space","Beside my accessible messaging device"],minutes:[2,5,10],fallback:["Ask a trusted person to arrange contact","Call the public health service appointment line","Retry my clinic at its next opening"],observation:["Contact attempted; reply or no reply","Appointment offered and next access step","Assistance requested and any response"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Call primary care for a sleep assessment",minimum:"Make one clinic contact attempt",minutes:2,cueHint:"At primary care’s next contact opening",placeHint:"At my kitchen table, phone ready",obstacleHint:"My clinic is unavailable or has not answered",fallbackHint:"Ask a trusted person to arrange contact",observationHint:"Contact attempted; reply or no reply",kind:"support"},stopRule:"Seek assessment for gasping or daytime sleepiness. Avoid sleepy driving; do not self-prescribe sleep restriction.",accessibleAlternative:"Use phone, text, or assisted contact. Name a reachable fallback person or public service before saving."},result:{question:"Did you carry out the next step you chose?",observationPrompt:"What move or care request happened, and what remains unresolved?"},judgment:{primary:{id:"sleep-5-decision",scenario:"Daniel’s persistent daytime sleepiness makes commuting unsafe despite rest changes. His clinic is open now; his public appointment line opens tomorrow.",question:"Which next step fits his records?",options:[{id:"sleep-5-more-records",text:"Ask his sister tonight to help arrange an appointment tomorrow, while using a safe travel alternative now.",feedback:"This protects travel and gets practical help. Because Daniel can contact the open clinic now, assistance tonight need not delay that request. He can ask his sister alongside it."},{id:"sleep-5-continue-changes",text:"Use safe transport now and call the public appointment line tomorrow for help finding an accessible clinician.",feedback:"That is a useful access route if his clinic cannot help. With the clinic open now, he can make the first assessment request today and keep tomorrow’s route as fallback."},{id:"sleep-5-contact-now",text:"Contact the clinic about daytime impairment now, keep optional notes, and arrange a safe travel alternative.",feedback:"This responds to the actual impact while preserving safety. Daniel does not need three months, a witness, or a finished diary before requesting appropriate assessment and discussing next steps."}],bestOptionId:"sleep-5-contact-now"}},carry:{takeaway:"Keep the useful move. Get care for the difficulty the move does not resolve.",followUp:{questionId:"sleep-5-return",question:"What happened with your rest move or care request, and what response or access step remains?",observationPrompt:"What was attempted, and what is still pending?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"Care does not wait for a course or a diary",paragraphs:["NHS insomnia guidance includes difficulty coping and habit changes that have not helped as reasons to contact care [S11]. Three months distinguishes a persistence category; it is not an instruction to wait. Sleep can be affected by work schedules, health, medication, and other conditions. This course cannot decide which explanation applies to you. A clinician can evaluate the problem and appropriate treatment.","Breathing interruptions, gasping or choking, and excessive daytime sleepiness warrant evaluation for possible sleep apnea or another cause [S12]. Loud snoring alone is not a diagnosis. Living alone does not disqualify you from asking for assessment. You can describe your own daytime impact or nighttime observations. Bring existing records if useful, but do not delay an appointment to complete a particular number of nights. Avoid driving or dangerous work when sleepy while arranging appropriate help."]},{heading:"What structured treatment can offer",paragraphs:["ACP recommends cognitive behavioral therapy for insomnia as initial treatment for chronic insomnia [S05]. Delivery can include individual or group care, telephone or web modules, and structured self-help formats. This does not make every digital sleep product validated treatment. Medication decisions require discussion with a clinician. ODA provides habit education and a record of controllable actions, which can support a conversation without replacing care.","Your final step is consolidation, not another nightly exercise. Look across any plans and attempts: which transition was feasible, what blocked it, and what difficulty remains? If no attempt was recorded, that outcome is unknown. Choose a first feasible opportunity or support. Carry forward one useful move or a care contact into the coming week. A request with no reply is still a real contact attempt, with a next access decision. No diary, course completion, or good quiz answer proves you slept well. You may pause the experiment while seeking assessment or practical help."]}],sourceIds:["S05","S11","S12"]}}],n=[{practice:["Choose a workable wake schedule; adapt it for shifts, care duties, and adequate sleep opportunity.","Plan adequate room for your own sleep need and settling time; begin winding down, not forced sleep.","For the next seven days, jot down a short note of when you went to bed and when you got up."],reflection:"What might make it hard to keep the wake-up time you chose?",question:"How should the adult sleep recommendation be read?",options:["Everyone must sleep exactly 8 hours.","At least 7 hours is a floor you aim to reach on most nights.","If you sleep badly one night, your health will definitely suffer."],correct:1,feedback:"The recommendation is a lower limit and is about regular habits. A single bad night is not the same as a pattern that lasts for a long time."},{practice:["Pick a feasible daylight opportunity; an indoor alternative is not established as equivalent to outdoor light.","Try a chosen screen handover before rest; practical durations are guidance, and needed contact stays available.","Choose a calm, dimly lit activity to replace the screen: a book, light stretching or music."],reflection:"At what time in the evening is it hardest for you to put the screen down?",question:"For evening screens, which is a starting point that fits the official recommendations?",options:["Using screens right up until you get into bed.","Winding down with a screen and all the lights fully on.","Putting screens away at least 30 minutes before bed."],correct:2,feedback:"The CDC’s 30-minute suggestion is practical guidance, not a precise threshold. Choose a feasible screen interval and replacement while preserving essential contact."},{practice:["Choose one actual late caffeine serving to move earlier, replace, or reduce gradually; no fixed cutoff guarantees sleep.","For one day, jot down every caffeinated drink you have.","Change one relevant habit first; do not impose a universal evening exercise ban or change prescribed medicines."],reflection:"Which of your evening habits seems easiest to change?",question:"What conclusion can be drawn from the Drake 2013 experiment?",options:["A high dose of caffeine taken 6 hours before bed can still shorten sleep.","Caffeine only affects sleep if taken right before bed.","Caffeine does not affect anyone’s sleep."],correct:0,feedback:"The small study tested one high 400-mg dose, which disrupted sleep even six hours before bed. It does not establish a universally safe cutoff or predict a lower serving’s effect."},{practice:["Choose a safe quiet alternative for sustained wakefulness; seek an accessible adaptation if getting up is unsafe.","Choose a suitable quiet activity there; comfortable breathing is optional, and essential access stays available.","Prepare a workable wind-down and conditional nighttime response without clock watching; avoid driving while sleepy."],reflection:"On a night when you can’t sleep, what would you like to say to yourself?",question:"What does stimulus-control guidance suggest during sustained wakefulness, without clock watching?",options:["Try harder to force yourself to sleep.","Start scrolling on your phone in bed.","Get up, do something quiet in low light and go back when you feel sleepy."],correct:2,feedback:"Use a safe quiet alternative and return when sleepy. Approximate minutes are not a biological deadline. Adapt for access and care needs; do not drive while sleepy."},{practice:["Review any sleep difficulty and daily impact; you do not have to wait three months to request assessment.","If available, another person’s observations can help; living alone does not prevent asking for care.","Contact care when warranted. Optional notes can accompany the appointment; do not delay contact for a two-week log."],reflection:"What might you gain from talking to a professional about your sleep?",question:"For chronic insomnia, which recommended treatment can you discuss with a clinician?",options:["Start sleeping pills on your own.","See a professional and talk about options such as CBT-I.","Assume that repeating this course will be enough."],correct:1,feedback:"ACP recommends CBT-I as initial treatment for chronic insomnia, with several delivery formats. Impairment or suspected apnea warrants timely care; this course does not replace assessment or treatment."}],a=[{id:"1767443522987-a83deb358199",alt:"Classic alarm clock on a wooden floor"},{id:"1527377761-f99968ed8a7f",alt:"Sunlight falling on the floor through a window"},{id:"1743689374053-be49ca407b7c",alt:"A cup of coffee by a window"},{id:"1789930445611-3b13fd7d6de4",alt:"Person reading a book by the light of a small desk lamp"},{id:"1653656120968-accae8452c9e",alt:"Woman sitting on a sofa talking with another woman"}],s={id:"sleep",title:"Still tired tomorrow? Protect your rest tonight",subtitle:"Five lessons to end one evening drain, keep needed contact, and review what your rest experiment actually changes.",description:"Protect a realistic rest opportunity, adjust one relevant obstacle, and use your records to choose a workable next week or timely care.",scope:"Sleep-habit education for adults, not diagnosis or treatment. Seek care when regular sleep trouble affects coping, changes are not helping, or gasping, breathing interruptions, or persistent daytime sleepiness occur. Living alone and unfinished notes do not delay assessment. Avoid driving or dangerous work when sleepy. Do not change medicines or prescribe yourself sleep restriction. Adapt plans to shifts, care, disability, and contact needs. Use appropriate urgent professional or crisis support for severe distress or self-harm thoughts, and local emergency care if you cannot stay safe or face immediate danger.",outcome:"One rest move you can repeat, honest action records, and a next-week or care step for the difficulty that remains.",photo:{id:"1606796913825-2b02883605e9",alt:"Bed with white sheets next to a green plant"},lessons:i.map((e,t)=>({id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,...n[t],takeaway:e.carry.takeaway,sources:t===1?[...e.goDeeper.sourceIds,"S08"]:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:{title:`Invented example: ${e.idea.example.title}`,text:e.idea.example.text},photo:a[t]}))};export{s as COURSE,i as LESSONS_V2,o as SOURCES};
